import{_ as h,C as l,o as d,c as p,a2 as n,E as a,w as o,j as t,a as s}from"./chunks/framework.Dh-DajNq.js";const C=JSON.parse('{"title":"Chapter 5: Caching Tiers & The Cache Stampede","description":"","frontmatter":{},"headers":[],"relativePath":"book/part-01-request-anatomy/chapter-05-caching-tiers-and-stampedes.md","filePath":"book/part-01-request-anatomy/chapter-05-caching-tiers-and-stampedes.md"}'),c={name:"book/part-01-request-anatomy/chapter-05-caching-tiers-and-stampedes.md"};function u(m,e,g,b,k,y){const r=l("Mermaid"),i=l("ClientOnly");return d(),p("div",null,[e[0]||(e[0]=n('<h1 id="chapter-5-caching-tiers-the-cache-stampede" tabindex="-1">Chapter 5: Caching Tiers &amp; The Cache Stampede <a class="header-anchor" href="#chapter-5-caching-tiers-the-cache-stampede" aria-label="Permalink to &quot;Chapter 5: Caching Tiers &amp; The Cache Stampede&quot;">​</a></h1><blockquote><p><em>&quot;A cache is an accelerator, not a shield; if your database collapses when the cache empties, you built a house of cards.&quot;</em></p></blockquote><hr><h2 id="_1-the-mystery-the-midnight-cliff" tabindex="-1">1. The Mystery: The Midnight Cliff <a class="header-anchor" href="#_1-the-mystery-the-midnight-cliff" aria-label="Permalink to &quot;1. The Mystery: The Midnight Cliff&quot;">​</a></h2><p>To protect the database during a multi-day festival sale, engineers cached the hot homepage catalog in Redis with a 24-hour TTL:</p><div class="language-javascript vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> redis.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">set</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;catalog:featured&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">JSON</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">stringify</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(data), </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;EX&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">86400</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>For 23 hours and 59 minutes, the system was untouchable: Redis absorbed 99.4% of traffic, and the database rested at 4% CPU.</p><p>Then midnight struck.</p>',8)),a(i,null,{default:o(()=>[a(r,{code:"flowchart%20TD%0A%20%20%20%20subgraph%20HappyPath%20%5B%2223%3A59%3A59%20(Cache%20Hit%20Ratio%3A%2099.4%25)%22%5D%0A%20%20%20%20%20%20%20%20T1%5B%2250%2C000%20req%2Fsec%22%5D%20--%3E%20R1%5B%22Redis%20Cluster%20(0.6ms%20response)%22%5D%0A%20%20%20%20%20%20%20%20R1%20--%3E%20U1%5B%22Shoppers%20Happy%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Disaster%20%5B%2200%3A00%3A00%20(TTL%20Expires%3A%20The%20Stampede)%22%5D%0A%20%20%20%20%20%20%20%20T2%5B%2250%2C000%20req%2Fsec%22%5D%20--%3E%20R2%5B%22Redis%3A%20Key%20Expired%20(MISS)%22%5D%0A%20%20%20%20%20%20%20%20R2%20--%3E%20DB%5B%2250%2C000%20Concurrent%20Queries%20Hit%20Database%22%5D%0A%20%20%20%20%20%20%20%20DB%20--%3E%20Crash%5B%22DB%20Connection%20Pool%20Exhausted%5CnCPU%20100%25%20%E2%86%92%20Crash%20Reboot%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20classDef%20default%20fill%3A%231e293b%2Cstroke%3A%233b82f6%2Cstroke-width%3A1.5px%2Ccolor%3A%23f8fafc%3B%0A%20%20%20%20classDef%20alert%20fill%3A%237c2d12%2Cstroke%3A%23ef4444%2Cstroke-width%3A2px%2Ccolor%3A%23fecaca%3B%0A%20%20%20%20class%20DB%2CCrash%20alert%3B%0A"})]),_:1}),e[1]||(e[1]=n('<p>At 00:00:00, the key vanished. Over the next 500 milliseconds, <strong>25,000 concurrent requests experienced a cache miss simultaneously</strong>. Every single request bypassed Redis and slammed the primary database with an expensive 8-table SQL join.</p><p>The database connection pool choked, thread queues overflowed, and the cluster crashed. This is the <strong>Cache Stampede</strong> (also known as the <em>Thundering Herd</em> or <em>Dogpiling</em>).</p><hr><h2 id="_2-multi-tier-caching-topology" tabindex="-1">2. Multi-Tier Caching Topology <a class="header-anchor" href="#_2-multi-tier-caching-topology" aria-label="Permalink to &quot;2. Multi-Tier Caching Topology&quot;">​</a></h2><p>A resilient architecture never relies on a single Redis instance. It deploys a defense-in-depth cache hierarchy:</p>',5)),a(i,null,{default:o(()=>[a(r,{code:"graph%20TD%0A%20%20%20%20User%5B%221.%20Client%20Browser%20Cache%5Cn(Cache-Control%3A%20max-age%2C%20stale-while-revalidate)%22%5D%20--%3E%20CDN%5B%222.%20Edge%20CDN%20Cache%20(Anycast%20POPs)%5Cn(Cloudflare%20%2F%20Fastly%3A%20Micro-caching%205s)%22%5D%0A%20%20%20%20CDN%20--%3E%20L1%5B%223.%20App%20Process%20In-Memory%20L1%5Cn(Caffeine%20%2F%20Guava%3A%20Zero%20Network%20Hop%2C%2050ns)%22%5D%0A%20%20%20%20L1%20--%3E%20L2%5B%224.%20Distributed%20L2%20Cache%5Cn(Redis%20Cluster%3A%20Shared%20State%2C%200.8ms)%22%5D%0A%20%20%20%20L2%20--%3E%20DB%5B%225.%20Authoritative%20Database%5Cn(PostgreSQL%20%2F%20MySQL%20with%20Covering%20Indexes)%22%5D%0A%0A%20%20%20%20classDef%20default%20fill%3A%231e293b%2Cstroke%3A%233b82f6%2Cstroke-width%3A1.5px%2Ccolor%3A%23f8fafc%3B%0A"})]),_:1}),e[2]||(e[2]=t("p",null,"If an item expires in Redis, L1 in-process caches and CDN edge micro-caches prevent requests from synchronously falling through to the primary database.",-1)),e[3]||(e[3]=t("hr",null,null,-1)),e[4]||(e[4]=t("h2",{id:"_3-neutralizing-the-stampede-mutexes-probabilistic-refresh",tabindex:"-1"},[s("3. Neutralizing the Stampede: Mutexes & Probabilistic Refresh "),t("a",{class:"header-anchor",href:"#_3-neutralizing-the-stampede-mutexes-probabilistic-refresh","aria-label":'Permalink to "3. Neutralizing the Stampede: Mutexes & Probabilistic Refresh"'},"​")],-1)),e[5]||(e[5]=t("p",null,"Three battle-tested architectural patterns eliminate the Thundering Herd:",-1)),e[6]||(e[6]=t("h3",{id:"pattern-a-distributed-mutex-singleflight",tabindex:"-1"},[s("Pattern A: Distributed Mutex (Singleflight) "),t("a",{class:"header-anchor",href:"#pattern-a-distributed-mutex-singleflight","aria-label":'Permalink to "Pattern A: Distributed Mutex (Singleflight)"'},"​")],-1)),e[7]||(e[7]=t("p",null,[s("Only the "),t("em",null,"first"),s(" thread that discovers a cache miss is allowed to query the database. All other incoming requests block and wait for the leader, or receive stale data:")],-1)),a(i,null,{default:o(()=>[a(r,{code:"sequenceDiagram%0A%20%20%20%20autonumber%0A%20%20%20%20participant%20Workers%20as%2010%2C000%20Concurrent%20Requests%0A%20%20%20%20participant%20Redis%20as%20Redis%20Cache%0A%20%20%20%20participant%20DB%20as%20Primary%20Database%0A%0A%20%20%20%20Workers-%3E%3ERedis%3A%20GET%20%22catalog%3Afeatured%22%20(Key%20Expired)%0A%20%20%20%20Redis--%3E%3EWorkers%3A%20Cache%20Miss%0A%20%20%20%20Note%20over%20Workers%3A%20Worker%20%231%20acquires%20Mutex%3A%20SETNX%20lock%3Acatalog%201%20EX%2010%0A%20%20%20%20Workers-%3E%3EDB%3A%20Worker%20%231%20queries%20DB%20(120ms)%0A%20%20%20%20Note%20over%20Workers%3A%20Workers%20%232..10%2C000%20wait%20or%20read%20stale%20copy%0A%20%20%20%20DB--%3E%3EWorkers%3A%20Worker%20%231%20receives%20fresh%20data%0A%20%20%20%20Workers-%3E%3ERedis%3A%20Worker%20%231%20writes%20new%20value%20%2B%20releases%20lock%0A%20%20%20%20Workers--%3E%3EWorkers%3A%20All%20waiting%20workers%20served%20from%20refreshed%20cache!%0A"})]),_:1}),e[8]||(e[8]=n('<h3 id="pattern-b-probabilistic-early-expiration-xfetch-algorithm" tabindex="-1">Pattern B: Probabilistic Early Expiration (XFetch Algorithm) <a class="header-anchor" href="#pattern-b-probabilistic-early-expiration-xfetch-algorithm" aria-label="Permalink to &quot;Pattern B: Probabilistic Early Expiration (XFetch Algorithm)&quot;">​</a></h3><p>Instead of waiting for the key to die, worker threads evaluate a probabilistic formula on every read:</p><p>$$\\Delta - \\beta \\times \\delta \\times \\ln(\\text{random}()) \\le 0$$</p><p>Where:</p><ul><li>$\\Delta$ = Time until expiration.</li><li>$\\delta$ = Time required to compute the database query.</li><li>$\\beta$ = Aggressiveness factor ($&gt; 0$).</li></ul><p>As the key nears expiration under heavy traffic, the probability that <em>one</em> background request triggers a pre-emptive refresh approaches 100%. <strong>The key never actually expires for users.</strong></p><h3 id="pattern-c-http-stale-while-revalidate" tabindex="-1">Pattern C: HTTP <code>stale-while-revalidate</code> <a class="header-anchor" href="#pattern-c-http-stale-while-revalidate" aria-label="Permalink to &quot;Pattern C: HTTP `stale-while-revalidate`&quot;">​</a></h3><p>Instruct clients and CDNs to serve stale data immediately while revalidating in the background:</p><div class="language-http vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Cache-Control</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> public, max-age=60, stale-while-revalidate=600</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Users experience a 2ms response time, while edge servers refresh content asynchronously.</p><hr><h2 id="_4-architect-level-trade-offs" tabindex="-1">4. Architect-Level Trade-Offs <a class="header-anchor" href="#_4-architect-level-trade-offs" aria-label="Permalink to &quot;4. Architect-Level Trade-Offs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Caching Pattern</th><th>Read Latency</th><th>Consistency Guarantee</th><th>Disaster Risk</th></tr></thead><tbody><tr><td><strong>Cache-Aside (Lazy)</strong></td><td>Fast on hits; slow on miss</td><td>Eventual (risk of serving stale data if DB updates)</td><td>Vulnerable to Cache Stampede without Singleflight.</td></tr><tr><td><strong>Write-Through</strong></td><td>Fast reads</td><td>High consistency (Cache &amp; DB updated together)</td><td>Higher write latency; caches data that may never be read.</td></tr><tr><td><strong>Write-Behind (Write-Back)</strong></td><td>Ultra-fast writes (memory speed)</td><td>Eventual; writes queued for batch DB sync</td><td>Data loss if Redis crashes before flushing to disk.</td></tr><tr><td><strong>Refresh-Ahead</strong></td><td>Instant (keys never expire)</td><td>High for predictable access patterns</td><td>Wasted compute refreshing keys nobody is reading.</td></tr></tbody></table><hr><h2 id="_5-mental-model-summary" tabindex="-1">5. Mental-Model Summary <a class="header-anchor" href="#_5-mental-model-summary" aria-label="Permalink to &quot;5. Mental-Model Summary&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>If a million users ask for the exact same data at the same moment, </span></span>\n<span class="line"><span>it is a failure of architecture if more than one request touches the database.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><ul><li><strong>Rule 1</strong>: Add jitter to cache TTLs (<code>TTL = base_ttl + rand(0, 300)</code>) to prevent simultaneous batch expirations.</li><li><strong>Rule 2</strong>: Use <strong>Singleflight / Distributed Locks</strong> or <strong>XFetch</strong> on hot read keys.</li></ul><hr><h2 id="_6-the-milestone-awaits" tabindex="-1">6. The Milestone Awaits <a class="header-anchor" href="#_6-the-milestone-awaits" aria-label="Permalink to &quot;6. The Milestone Awaits&quot;">​</a></h2><p>We have traced the foundational anatomy of software end-to-end:</p><ol><li><strong>Network Physics &amp; Handshakes</strong> (<a href="/systems-beyond-the-code/book/part-01-request-anatomy/chapter-01-anatomy-of-a-keystroke.html">Chapter 1</a>)</li><li><strong>Browser Rendering &amp; Hydration</strong> (<a href="/systems-beyond-the-code/book/part-01-request-anatomy/chapter-02-browser-execution-cycle.html">Chapter 2</a>)</li><li><strong>Ingress &amp; Event Loops</strong> (<a href="/systems-beyond-the-code/book/part-01-request-anatomy/chapter-03-request-meets-backend.html">Chapter 3</a>)</li><li><strong>Database Indexing &amp; Disk I/O</strong> (<a href="/systems-beyond-the-code/book/part-01-request-anatomy/chapter-04-database-indexing-mechanics.html">Chapter 4</a>)</li><li><strong>Multi-Tier Caching &amp; Invalidation</strong> (<a href="/systems-beyond-the-code/book/part-01-request-anatomy/chapter-05-caching-tiers-and-stampedes.html">Chapter 5</a>)</li></ol><p>Now, we integrate these five building blocks into our first complete, production-grade system design.</p><p>👉 <strong>Next: <a href="/systems-beyond-the-code/book/part-01-request-anatomy/chapter-06-case-study-planetary-url-shortener.html">Chapter 6 — Complete Case Study: Designing a Planetary URL Shortener</a></strong></p>',23))])}const A=h(c,[["render",u]]);export{C as __pageData,A as default};
